class vector3d
{
public:
    float x;
    float y;
    float z;
};

class vector4d
{
public:
    float x;
    float y;
    float z;
    float w;
};

class matrix4x4
{
public:
    vector4d x __attribute__((aligned(16)));
    vector4d y;
    vector4d z;
    vector4d w;

    vector3d& xrow() { return *(vector3d*)&x; }
    vector3d& yrow() { return *(vector3d*)&y; }
    vector3d& zrow() { return *(vector3d*)&z; }
    vector3d& wrow() { return *(vector3d*)&w; }
};

extern const matrix4x4 identity_matrix;

void ReadVector3d(vector3d& v, unsigned char* buffer, int& index);

void ReadMatrix3x4(matrix4x4& matrix, unsigned char* buffer, int& index)
{
	matrix = identity_matrix;
	ReadVector3d(matrix.xrow(), buffer, index);
	ReadVector3d(matrix.yrow(), buffer, index);
	ReadVector3d(matrix.zrow(), buffer, index);
	ReadVector3d(matrix.wrow(), buffer, index);
}
